def lcm(self, g: PolyElement[Er]) -> PolyElement[Er]:
    f = self
    domain = f.ring.domain

    if (not f or not g) and f.ring == g.ring:
        return f.ring.zero

    if not f or not g:
        raise ValueError("self and f must have the same ring")

    if not domain.is_Field:
        fc, f = f.primitive()
        gc, g = g.primitive()
        c = domain.lcm(fc, gc)
        h = (f * g).quo(f.gcd(g))
        return h.mul_ground(c)
    else:
        h = (f * g).quo(f.gcd(g))
        return h.monic()

